      sb_version: 'Current version', sb_date: 'Released', sb_setup: 'Setup', sb_zip: 'Portable ZIP', sb_zip_link: 'download',
      sb_zip_note: 'No setup: unzip and run. With an empty file portable.txt next to MailVault.exe everything stays in the program folder, e.g. on a USB stick.',
